"""Independent JOSE fixtures; cryptography is test tooling, never a runtime dependency.

All keys are disposable public test material. Regeneration changes RSA keys and
probabilistic signatures/ciphertexts. The CTest test consumes only the C header.
"""
from pathlib import Path
import base64
import hashlib
import hmac
import json
from cryptography.hazmat.primitives import hashes, serialization as s
from cryptography.hazmat.primitives.asymmetric import rsa, ec, ed25519, ed448, padding, utils
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives.keywrap import aes_key_wrap

def b64(data):
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode()

def compact(value):
    return json.dumps(value, separators=(',',':'))

def number(value, size=None):
    return b64(value.to_bytes(size or (value.bit_length()+7)//8, 'big'))

def string(data):
    if isinstance(data,bytes): data=data.decode()
    return '\n'.join('    '+json.dumps(data[i:i+96]) for i in range(0,len(data),96)) or '    ""'

rsa_key = rsa.generate_private_key(65537,2048)
ec_keys = [ec.derive_private_key(7,c) for c in [ec.SECP256R1(),ec.SECP384R1(),ec.SECP521R1(),ec.SECP256K1()]]
ed_keys = [ed25519.Ed25519PrivateKey.from_private_bytes(bytes(range(32))),ed448.Ed448PrivateKey.from_private_bytes(bytes(range(57))) ]
rsa_priv = rsa_key.private_bytes(s.Encoding.PEM,s.PrivateFormat.PKCS8,s.NoEncryption())
rsa_pub = rsa_key.public_key().public_bytes(s.Encoding.PEM,s.PublicFormat.SubjectPublicKeyInfo)
rn = rsa_key.private_numbers()
rsa_jwk = dict(kty='RSA',n=number(rn.public_numbers.n),e=number(rn.public_numbers.e))
rsa_jwk_private = dict(rsa_jwk,d=number(rn.d))  # Deliberately omit CRT.
out = ['/* Generated by generate_salts_vectors.py; disposable public test keys. */',
       'static const struct { cjwt_alg_t alg; const char *private_key, *public_key, *public_jwk, *private_jwk, *token; } jws_vectors[] = {']
payload = b64(b'{"iss":"migration"}')
names = ['HS256','HS384','HS512','RS256','RS384','RS512','PS256','PS384','PS512','ES256','ES384','ES512','ES256K','EdDSA','EdDSA']
for i,name in enumerate(names):
    header = b64(compact(dict(alg=name)).encode())
    message = (header+'.'+payload).encode()
    width = {'256':32,'384':48,'512':64}.get(name[-3:],32)
    hash_name = {32:'sha256',48:'sha384',64:'sha512'}[width]
    md = {32:hashes.SHA256(),48:hashes.SHA384(),64:hashes.SHA512()}[width]
    if name.startswith('HS'):
        private=public=b'interoperability-secret'
        sig=hmac.new(private,message,hash_name).digest()
        pub_jwk=priv_jwk=dict(kty='oct',k=b64(private))
    elif name.startswith(('RS','PS')):
        private,public=rsa_priv,rsa_pub
        # PSS max salt tests compatibility with peers using non-digest salt lengths.
        pad=padding.PKCS1v15() if name.startswith('RS') else padding.PSS(padding.MGF1(md),padding.PSS.MAX_LENGTH)
        sig=rsa_key.sign(message,pad,md)
        pub_jwk,priv_jwk=rsa_jwk,rsa_jwk_private
    else:
        key=ec_keys[i-9] if i < 13 else ed_keys[i-13]
        private=key.private_bytes(s.Encoding.PEM,s.PrivateFormat.PKCS8,s.NoEncryption())
        public=key.public_key().public_bytes(s.Encoding.PEM,s.PublicFormat.SubjectPublicKeyInfo)
        if i < 13:
            r,v=utils.decode_dss_signature(key.sign(message,ec.ECDSA(md)))
            n=(key.key_size+7)//8
            sig=r.to_bytes(n,'big')+v.to_bytes(n,'big')
            point=key.public_key().public_numbers()
            pub_jwk=dict(kty='EC',crv=['P-256','P-384','P-521','secp256k1'][i-9],x=number(point.x,n),y=number(point.y,n))
            priv_jwk=dict(pub_jwk,d=number(7,n))
        else:
            sig=key.sign(message)
            pub_jwk=dict(kty='OKP',crv='Ed25519' if i==13 else 'Ed448',x=b64(key.public_key().public_bytes(s.Encoding.Raw,s.PublicFormat.Raw)))
            priv_jwk=dict(pub_jwk,d=b64(key.private_bytes(s.Encoding.Raw,s.PrivateFormat.Raw,s.NoEncryption())))
    token=message.decode()+'.'+b64(sig)
    out.append('  { alg_%s,\n%s },' % (name.lower(),',\n'.join(string(x) for x in [private,public,compact(pub_jwk),compact(priv_jwk),token])))
out += ['};', 'static const char rsa_private_pem[] =\n'+string(rsa_priv)+';',
        'static const char rsa_public_pem[] =\n'+string(rsa_pub)+';',
        'static const char rsa_private_jwk[] =\n'+string(compact(rsa_jwk_private))+';',
        'static const struct { cjwt_alg_t alg; cjwt_enc_t enc; const char *key_hex, *token, *p2s; } jwe_vectors[] = {']
algs = [('dir','dir'),('RSA-OAEP','rsa_oaep'),('RSA-OAEP-256','rsa_oaep_256'),('A128KW','a128kw'),('A192KW','a192kw'),('A256KW','a256kw'),('PBES2-HS256+A128KW','pbes2_hs256_a128kw'),('PBES2-HS384+A192KW','pbes2_hs384_a192kw'),('PBES2-HS512+A256KW','pbes2_hs512_a256kw')]
for i,(alg,ident) in enumerate(algs):
    for enc_size in [16,24,32]:
        enc='A%dGCM' % (8*enc_size)
        header=dict(alg=alg,enc=enc)
        cek=bytes(range(enc_size))
        key=bytes(range(enc_size)) if i==0 else b''
        p2s=''
        if i==0: encrypted=b''
        elif i<=2:
            md=hashes.SHA1() if i==1 else hashes.SHA256()
            encrypted=rsa_key.public_key().encrypt(cek,padding.OAEP(padding.MGF1(md),md,None))
        else:
            size=[16,24,32][(i-3)%3]
            key=bytes(range(size)) if i<6 else b'interoperability-password'
            kek=key
            if i>=6:
                salt=bytes(range(80))
                p2s=b64(salt)
                header.update(p2s=p2s,p2c=2)
                kek=hashlib.pbkdf2_hmac(['sha256','sha384','sha512'][i-6],key,alg.encode()+b'\0'+salt,2,size)
            encrypted=aes_key_wrap(kek,cek)
        aad=b64(compact(header).encode())
        nonce=bytes([i,enc_size])+bytes(10)
        content=AESGCM(cek).encrypt(nonce,b'{"iss":"migration"}',aad.encode())
        token='.'.join([aad,b64(encrypted),b64(nonce),b64(content[:-16]),b64(content[-16:])])
        out.append('  { alg_%s, enc_%s,\n%s },' % (ident,enc.lower(),',\n'.join(string(x) for x in [key.hex(),token,p2s])))
out += ['};','']
Path(__file__).with_name('salts_vectors.h').write_text('\n'.join(out))
